# 0037-35.01 Clean Regeneration Verifier -- real fresh-re-execution design
# Specification ID: 0037-35.01-clean-regeneration-verifier@v1
# Generation Domain: issue-cutover-clean-regeneration-verification@v1
#
# This verifier does not trust the reference JSON's own claims about what was
# executed. It extracts the retained harness source, writes it to a temp
# file, verifies its SHA-256, and RE-RUNS it fresh (one real run: fresh
# clone, fresh checkout, real red-control --check call, real independent
# canonical validation, real direct stage-handler DAG execution) against the
# exact same frozen baseline. It then compares the freshly obtained result
# against the recorded run_1 in the reference JSON. Any mismatch, any
# templated/placeholder text where a literal value is required, any missing
# git object, or any inconsistency between the two recorded runs (run_1 vs
# run_2) is a hard failure. This is what defeats "templated commands",
# "nonexistent repo accepted", "no executable disposition path", "shallow
# oversized coverage", "bad lineage OIDs", and "stale receipts" as a class:
# none of those survive an actual independent re-execution and byte
# comparison, because there is nothing to inspect other than real files.

import hashlib
import json
import subprocess
import sys
import tempfile
from pathlib import Path


class RegenVerificationError(Exception):
    pass


# Externally anchored trust root for the harness source. This constant is
# NOT read from the candidate JSON under verification -- it is a literal
# baked into this verifier file itself, which the reviewer runs as an
# independent artifact (not reconstructed from the JSON's own self-reported
# fields). Defeats the circular-trust attack: replacing BOTH source_code and
# source_sha256 consistently inside the JSON still cannot make this
# hardcoded external comparison pass, because the attacker would also have
# to modify this separately-reviewed verifier file itself -- a materially
# different, human-detectable act, not a JSON edit.
# Recomputed and pinned literally after the 0037-35.01-rework-5 harness
# reached its final form (25-output bootstrap+DAG execution, tool pins,
# tree_oid, source-invariance proof, doctor fresh/stale, deep oversized
# semantics). Set to None until the harness is finalized in this round;
# verify_all treats None as "trust root not yet established" and fails
# closed rather than silently skipping the check.
EXPECTED_HARNESS_SOURCE_SHA256 = "sha256:cad44da302ccc591e02bb5affad12642c753f26574fb5d9b104cad7e6f6e120d"


def sha256_bytes(b):
    return "sha256:" + hashlib.sha256(b).hexdigest()


def run_git(args, cwd):
    res = subprocess.run(["git"] + args, cwd=cwd, capture_output=True, text=True)
    return res.returncode, res.stdout.strip(), res.stderr.strip()


PLACEHOLDER_MARKERS = ("<out>", "<tmp>", "<clone_path>", "<absolute-tmp>", "(render to", "...")


def _reject_placeholders(value, where):
    if isinstance(value, str):
        for marker in PLACEHOLDER_MARKERS:
            if marker in value:
                raise RegenVerificationError(f"Templated/placeholder text detected in {where}: {value!r}")
    elif isinstance(value, dict):
        for k, v in value.items():
            _reject_placeholders(v, f"{where}.{k}")
    elif isinstance(value, list):
        for i, v in enumerate(value):
            _reject_placeholders(v, f"{where}[{i}]")


def verify_lineage(repo_dir, commits_and_expected_parents):
    """commits_and_expected_parents: list of (commit, expected_first_parent_or_None)."""
    for commit, expected_parent in commits_and_expected_parents:
        code, out, err = run_git(["cat-file", "-e", commit], repo_dir)
        if code != 0:
            raise RegenVerificationError(f"Bad lineage OID: {commit} does not exist in {repo_dir}: {err}")
        if expected_parent is not None:
            code, out, err = run_git(["log", "-1", "--format=%P", commit], repo_dir)
            if code != 0:
                raise RegenVerificationError(f"Git ancestry query failed for {commit}: {err}")
            parents = out.split()
            if expected_parent not in parents:
                raise RegenVerificationError(
                    f"Bad lineage OID: {commit} parents {parents} do not include expected {expected_parent}"
                )
    return True


def run_fresh(repo_dir, harness_source, baseline_oid):
    """Write the retained harness source to a temp file and run ONE fresh
    clone+checkout+red-control+validate+DAG cycle by calling its internal
    do_one_run() function directly (not the whole run_1+run_2 __main__),
    against a temp output directory, so verify_all stays bounded to a single
    real run rather than repeating both."""
    tmp_dir = tempfile.mkdtemp(prefix="verify-0037-35-01-", dir="/private/tmp")
    harness_path = Path(tmp_dir) / "harness.py"
    harness_path.write_text(harness_source)
    driver = f"""
import sys, json
sys.path.insert(0, {str(Path(tmp_dir))!r})
import importlib.util
spec = importlib.util.spec_from_file_location("harness_fresh", {str(harness_path)!r})
h = importlib.util.module_from_spec(spec)
spec.loader.exec_module(h)
h.OUT = __import__("pathlib").Path({tmp_dir!r}) / "runs"
h.ROOT = {str(repo_dir)!r}
h.BASELINE = {baseline_oid!r}
result = h.do_one_run("verify-fresh")
print(json.dumps(result))
"""
    driver_path = Path(tmp_dir) / "driver.py"
    driver_path.write_text(driver)
    res = subprocess.run(["python3", str(driver_path)], capture_output=True, text=True, timeout=600)
    if res.returncode != 0:
        raise RegenVerificationError(f"Fresh re-execution failed: exit {res.returncode}, stderr: {res.stderr[-2000:]}")
    try:
        return json.loads(res.stdout.strip().splitlines()[-1])
    except Exception as exc:
        raise RegenVerificationError(f"Fresh re-execution produced non-JSON output: {exc}; stdout tail: {res.stdout[-500:]}")


def verify_all(reference_json_path, repo_dir):
    with open(reference_json_path, "rb") as f:
        data = json.load(f)

    # 1. Reject templated/placeholder text anywhere in the harness-adjacent
    #    recorded fields (defeats "templated commands accepted").
    _reject_placeholders(data.get("run_1"), "run_1")
    _reject_placeholders(data.get("run_2"), "run_2")
    _reject_placeholders(data.get("harness_specification", {}).get("source_reference"), "harness_specification.source_reference")

    # 1b. Envelope check: schema/task_id must be exactly the expected
    #    literal values and no unknown top-level field may silently replace
    #    a required one (defeats a combined bogus-schema + bogus-task_id +
    #    unknown-field substitution).
    EXPECTED_SCHEMA = "clean-regeneration-evidence@v2"
    EXPECTED_TASK_ID = "0037-35.01"
    if data.get("schema") != EXPECTED_SCHEMA:
        raise RegenVerificationError(f"schema mismatch: expected {EXPECTED_SCHEMA!r}, got {data.get('schema')!r}")
    if data.get("task_id") != EXPECTED_TASK_ID:
        raise RegenVerificationError(f"task_id mismatch: expected {EXPECTED_TASK_ID!r}, got {data.get('task_id')!r}")
    required_top_level = {
        "schema", "task_id", "signer_authority", "baseline", "ordering_incident_record",
        "harness_specification", "run_1", "run_2", "determinism_comparison",
        "no_source_mutation_proof", "non_operational_guards", "fresh_agent_result",
        "management_decision", "integrator_receipts", "verifier_specification",
        "adversarial_negative_results",
    }
    missing_top = required_top_level - set(data.keys())
    if missing_top:
        raise RegenVerificationError(f"Missing required top-level keys: {sorted(missing_top)}")

    # 2. Harness source self-check PLUS externally anchored trust root.
    #    Self-consistency alone (source_code hash == source_sha256, both
    #    read from the same JSON) is insufficient: an attacker can replace
    #    both fields consistently (e.g. swap do_one_run for an inert stub
    #    that returns the recorded run_1 verbatim, then recompute a matching
    #    hash) and self-consistency alone would still report True. The
    #    hardcoded EXPECTED_HARNESS_SOURCE_SHA256 constant above -- baked
    #    into this verifier file, never read from the candidate JSON -- is
    #    the externally anchored comparison that closes that loop.
    hs = data["harness_specification"]
    actual_source_hash = sha256_bytes(hs["source_code"].encode("utf-8"))
    if actual_source_hash != hs["source_sha256"]:
        raise RegenVerificationError(f"Harness source hash mismatch: expected {hs['source_sha256']}, got {actual_source_hash}")
    if EXPECTED_HARNESS_SOURCE_SHA256 is None:
        raise RegenVerificationError(
            "No externally anchored harness-source trust root is set in this verifier "
            "(EXPECTED_HARNESS_SOURCE_SHA256 is None) -- fail closed rather than trust the "
            "JSON's self-reported hash alone."
        )
    if actual_source_hash != EXPECTED_HARNESS_SOURCE_SHA256:
        raise RegenVerificationError(
            f"Harness source does not match this verifier's externally anchored trust root: "
            f"expected {EXPECTED_HARNESS_SOURCE_SHA256}, candidate JSON declares {actual_source_hash}. "
            f"The embedded harness may have been substituted even though its own self-reported hash matches itself."
        )

    # 3. Lineage checks (defeats "bad lineage OIDs").
    baseline = data["baseline"]
    verify_lineage(repo_dir, [
        (baseline["start_commit"], None),
        (baseline["cutover_commit"], None),
        (baseline["control_commit"], None),
    ] + [(c, None) for c in baseline.get("documented_history", {}).values() if isinstance(c, str)])

    # 4. Determinism: run_1 and run_2 must be byte-identical on all 17
    #    outputs and on the canonical-validation digest.
    m1 = data["run_1"]["dag_execution"]["manifest"]
    m2 = data["run_2"]["dag_execution"]["manifest"]
    if m1 != m2:
        raise RegenVerificationError("run_1 and run_2 DAG output manifests are not byte-identical")
    if data["run_1"]["canonical_validation"]["sorted_diagnostics_sha256"] != data["run_2"]["canonical_validation"]["sorted_diagnostics_sha256"]:
        raise RegenVerificationError("run_1 and run_2 canonical-validation digests differ")
    # 4a2. Recompute the digest from the recorded sorted_diagnostics content
    #    itself (exact same serialization the harness used: sort_keys=True,
    #    separators=(",", ":")) and require it to match the recorded
    #    sorted_diagnostics_sha256 -- defeats a diagnostic-text mutation
    #    left in place without a corresponding digest update.
    for run_key in ("run_1", "run_2"):
        cv = data[run_key]["canonical_validation"]
        recomputed = sha256_bytes(json.dumps(cv["sorted_diagnostics"], sort_keys=True, separators=(",", ":")).encode())
        if recomputed != cv["sorted_diagnostics_sha256"]:
            raise RegenVerificationError(
                f"{run_key} sorted_diagnostics content does not hash to its own recorded sorted_diagnostics_sha256: "
                f"recomputed {recomputed}, recorded {cv['sorted_diagnostics_sha256']} -- diagnostic text mutated without digest update"
            )
        if len(cv["sorted_diagnostics"]) != cv.get("total_diagnostics"):
            raise RegenVerificationError(
                f"{run_key} sorted_diagnostics length {len(cv['sorted_diagnostics'])} does not match total_diagnostics {cv.get('total_diagnostics')}"
            )
    if len(m1) != 17:
        raise RegenVerificationError(f"Expected exactly 17 DAG outputs, got {len(m1)}")
    if data["run_1"]["canonical_validation"].get("total_diagnostics") != 244:
        raise RegenVerificationError(
            f"run_1 recorded total_diagnostics expected 244, got {data['run_1']['canonical_validation'].get('total_diagnostics')}"
        )
    if data["run_2"]["canonical_validation"].get("total_diagnostics") != 244:
        raise RegenVerificationError(
            f"run_2 recorded total_diagnostics expected 244, got {data['run_2']['canonical_validation'].get('total_diagnostics')}"
        )
    if data["run_1"]["red_control"]["exit_code"] != 2:
        raise RegenVerificationError(f"run_1 red_control exit_code expected 2 (real IR1020), got {data['run_1']['red_control']['exit_code']}")
    if "IR1020" not in data["run_1"]["red_control"]["stderr"]:
        raise RegenVerificationError("run_1 red_control stderr does not contain the real IR1020 marker")

    # 4b. Bootstrap refresh: 8 real outputs (2 views + 6 lists, excluding
    #    "manifest"), IR1031 pinned disposition present, byte-identical
    #    between run_1/run_2, for the full 25-output (8 bootstrap + 17 DAG)
    #    contract.
    for run_key in ("run_1", "run_2"):
        be = data[run_key].get("bootstrap_execution") or {}
        if be.get("exit_code") != 0:
            raise RegenVerificationError(f"{run_key} bootstrap_execution exit_code expected 0, got {be.get('exit_code')}")
        if be.get("output_count") != 8:
            raise RegenVerificationError(f"{run_key} bootstrap_execution expected exactly 8 outputs, got {be.get('output_count')}")
        if len(be.get("manifest") or {}) != 8:
            raise RegenVerificationError(f"{run_key} bootstrap_execution manifest length expected 8, got {len(be.get('manifest') or {})}")
        vp = be.get("validation_payload_pinned") or {}
        if vp.get("exit_code") != 2:
            raise RegenVerificationError(f"{run_key} bootstrap pinned _validate_payload(include_provenance=False) exit_code expected 2 (real red baseline), got {vp.get('exit_code')}")
        if not be.get("ir1031_would_raise"):
            raise RegenVerificationError(f"{run_key} bootstrap_execution does not record that real IR1031 would have raised")
    if data["run_1"]["bootstrap_execution"]["manifest"] != data["run_2"]["bootstrap_execution"]["manifest"]:
        raise RegenVerificationError("run_1 and run_2 bootstrap output manifests are not byte-identical")
    total_outputs_r1 = len(data["run_1"]["dag_execution"]["manifest"]) + len(data["run_1"]["bootstrap_execution"]["manifest"])
    if total_outputs_r1 != 25:
        raise RegenVerificationError(f"Expected exactly 25 total outputs (8 bootstrap + 17 DAG), got {total_outputs_r1}")

    # 4c. Real agent_bootstrap.py doctor execution, both fresh (ready/exit 0)
    #    and stale (stale-or-invalid/exit 2 with the 3 real AB017/018/019
    #    diagnostics) -- a rejected-fresh-doctor status is a hard failure.
    for run_key in ("run_1", "run_2"):
        df = data[run_key].get("doctor_fresh") or {}
        if df.get("exit_code") != 0:
            raise RegenVerificationError(f"{run_key} doctor_fresh exit_code expected 0, got {df.get('exit_code')}")
        try:
            df_payload = json.loads(df.get("stdout") or "")
        except Exception as exc:
            raise RegenVerificationError(f"{run_key} doctor_fresh stdout not valid JSON: {exc}")
        if df_payload.get("status") != "ready":
            raise RegenVerificationError(f"{run_key} doctor_fresh status expected 'ready', got {df_payload.get('status')}")
        if df_payload.get("diagnostics"):
            raise RegenVerificationError(f"{run_key} doctor_fresh has unexpected diagnostics: {df_payload.get('diagnostics')}")
        ds = data[run_key].get("doctor_stale") or {}
        if ds.get("exit_code") != 2:
            raise RegenVerificationError(f"{run_key} doctor_stale exit_code expected 2, got {ds.get('exit_code')}")
        try:
            ds_payload = json.loads(ds.get("stdout") or "")
        except Exception as exc:
            raise RegenVerificationError(f"{run_key} doctor_stale stdout not valid JSON: {exc}")
        if ds_payload.get("status") != "stale-or-invalid":
            raise RegenVerificationError(f"{run_key} doctor_stale status expected 'stale-or-invalid', got {ds_payload.get('status')}")
        diag_ids = {d.get("id") for d in (ds_payload.get("diagnostics") or [])}
        if not {"AB017_EXPECTED_EPOCH", "AB018_EXPECTED_PROFILE", "AB019_EXPECTED_VERSION"} <= diag_ids:
            raise RegenVerificationError(f"{run_key} doctor_stale missing expected AB017/018/019 diagnostics: {diag_ids}")

    # 4d. Writes-enabled guard: no captured subprocess argv in either run may
    #    contain a --write flag; this evidence must be produced entirely in
    #    check/no-op mode.
    for run_key in ("run_1", "run_2"):
        for step in data[run_key].get("steps", []):
            argv = step.get("argv") or []
            if "--write" in argv or any(str(a) == "--write" for a in argv):
                raise RegenVerificationError(f"{run_key} step {step.get('name')} argv contains --write: {argv}")

    # 4e. tree_oid must be a real, non-null, well-formed 40-hex object id
    #    (defeats "null tree_oid" gap), and must equal the independently
    #    computed tree of the exact baseline commit.
    tree_oid = baseline.get("tree_oid")
    if not (isinstance(tree_oid, str) and len(tree_oid) == 40 and all(c in "0123456789abcdef" for c in tree_oid.lower())):
        raise RegenVerificationError(f"baseline.tree_oid is missing or malformed: {tree_oid!r}")
    for run_key in ("run_1", "run_2"):
        if data[run_key].get("baseline_tree_oid") != tree_oid:
            raise RegenVerificationError(f"{run_key} baseline_tree_oid {data[run_key].get('baseline_tree_oid')!r} does not match baseline.tree_oid {tree_oid!r}")

    # 4f. Tool/dependency/config pins: all 6 named tool files must carry a
    #    real, present, well-formed sha256 pin, identical between run_1/run_2.
    expected_tools = {
        "_src/tools/issue_regenerate.py", "_src/tools/issue_validate.py",
        "_src/tools/issuectl.py", "_src/tools/agent_bootstrap.py",
        "_src/tools/issue_views.py", "_src/tools/issue_lists.py",
    }
    for run_key in ("run_1", "run_2"):
        pins = data[run_key].get("tool_pins") or {}
        if set(pins.keys()) != expected_tools:
            raise RegenVerificationError(f"{run_key} tool_pins path set mismatch: {sorted(pins.keys())}")
        for path, digest in pins.items():
            if not (isinstance(digest, str) and digest.startswith("sha256:") and len(digest) == 71):
                raise RegenVerificationError(f"{run_key} tool_pins[{path}] missing/malformed: {digest!r}")
    if data["run_1"]["tool_pins"] != data["run_2"]["tool_pins"]:
        raise RegenVerificationError("run_1 and run_2 tool_pins differ (tool substitution between runs)")

    # 4g. Post-run tracked-source invariance proof: issues/ and provenance/
    #    must be provably byte-unchanged across the entire direct-handler
    #    execution span in both runs (reimplements the IR1026 guard lost by
    #    bypassing _execute_locked).
    for run_key in ("run_1", "run_2"):
        sip = data[run_key].get("source_invariance_proof") or {}
        if not sip.get("issues_unchanged"):
            raise RegenVerificationError(f"{run_key} source_invariance_proof reports issues/ mutated during execution")
        if not sip.get("provenance_unchanged"):
            raise RegenVerificationError(f"{run_key} source_invariance_proof reports provenance/ mutated during execution")
        if sip.get("pre_issues_sha256") != sip.get("post_issues_sha256"):
            raise RegenVerificationError(f"{run_key} source_invariance_proof pre/post issues/ digest mismatch despite issues_unchanged flag")
        if sip.get("pre_provenance_sha256") != sip.get("post_provenance_sha256"):
            raise RegenVerificationError(f"{run_key} source_invariance_proof pre/post provenance/ digest mismatch despite provenance_unchanged flag")

    # 5. Oversized-input coverage: all three named paths must have a real
    #    whole-file SHA-256 and confirmed valid JSON (defeats "shallow
    #    oversized coverage").
    expected_oversized = {
        "provenance/migrations/issue-store/0037-13-20260825T082600Z/legacy-inventory.json",
        "provenance/migrations/issue-store/0037-31-final-frozen-candidate.json",
        "provenance/migrations/issue-store/0037-31-promotion/migration-dispositions.json",
    }
    cov = data["run_1"]["oversized_coverage"]
    if set(cov.keys()) != expected_oversized:
        raise RegenVerificationError(f"Oversized coverage path set mismatch: {sorted(cov.keys())}")
    for path, info in cov.items():
        if not info.get("exists") or not info.get("valid_json") or not info.get("sha256", "").startswith("sha256:") or not info.get("size_bytes", 0) > 262144:
            raise RegenVerificationError(f"Shallow or missing oversized coverage for {path}: {info}")
        if not info.get("duplicate_key_free"):
            raise RegenVerificationError(f"Oversized coverage for {path} reports duplicate JSON keys: {info.get('duplicate_keys')}")
        sc = info.get("semantic_checks") or {}
        if path.endswith("legacy-inventory.json"):
            if sc.get("item_id_duplicates") not in (0, None) or sc.get("claim_path_duplicates") not in (0, None):
                raise RegenVerificationError(f"legacy-inventory.json semantic check found duplicate IDs/paths: {sc}")
            if not sc.get("items_have_valid_text_sha256") or not sc.get("claims_have_valid_sha256"):
                raise RegenVerificationError(f"legacy-inventory.json semantic check found malformed sha256 references: {sc}")
        elif path.endswith("0037-31-final-frozen-candidate.json"):
            if not sc.get("required_keys_present"):
                raise RegenVerificationError(f"0037-31-final-frozen-candidate.json missing required keys: {sc.get('missing_keys')}")
        elif path.endswith("migration-dispositions.json"):
            if not sc.get("entries_count_matches_dec_0037_034_930"):
                raise RegenVerificationError(f"migration-dispositions.json entries_count does not match DEC-0037-034's 930: {sc.get('entries_count')}")
            if sc.get("finding_id_duplicates") not in (0, None):
                raise RegenVerificationError(f"migration-dispositions.json has duplicate finding_id values: {sc}")
            if sc.get("entries_missing_required_keys_count") not in (0, None):
                raise RegenVerificationError(f"migration-dispositions.json has entries missing required keys: {sc}")
            if not sc.get("evidence_refs_all_nonempty_lists") or not sc.get("evidence_refs_all_strings"):
                raise RegenVerificationError(f"migration-dispositions.json has malformed evidence_refs: {sc}")
            if not sc.get("decided_at_all_iso8601z"):
                raise RegenVerificationError(f"migration-dispositions.json has non-ISO8601 decided_at values: {sc}")

    # 6. THE independent fresh re-execution: this is the load-bearing check.
    #    Re-run the retained harness fresh, for real, against the exact
    #    frozen baseline, and require the freshly obtained result to match
    #    the recorded run_1 on every load-bearing fact.
    fresh = run_fresh(repo_dir, hs["source_code"], baseline["start_commit"])
    if fresh.get("resolved_head") != baseline["start_commit"]:
        raise RegenVerificationError(f"Fresh re-execution resolved wrong HEAD: {fresh.get('resolved_head')}")
    if not fresh.get("clone_clean"):
        raise RegenVerificationError("Fresh re-execution clone was not clean")
    if fresh.get("red_control", {}).get("exit_code") != 2:
        raise RegenVerificationError(f"Fresh re-execution red_control exit_code expected 2, got {fresh.get('red_control', {}).get('exit_code')}")
    if fresh.get("dag_execution", {}).get("exit_code") != 0:
        raise RegenVerificationError(f"Fresh re-execution DAG exit_code expected 0, got {fresh.get('dag_execution', {}).get('exit_code')}")
    fresh_manifest = fresh.get("dag_execution", {}).get("manifest")
    if fresh_manifest != m1:
        diff_keys = [k for k in set(fresh_manifest) | set(m1) if fresh_manifest.get(k) != m1.get(k)]
        raise RegenVerificationError(f"Fresh re-execution DAG manifest does not match recorded run_1 on: {diff_keys[:10]}")
    fresh_cv = fresh.get("canonical_validation", {})
    if fresh_cv.get("sorted_diagnostics_sha256") != data["run_1"]["canonical_validation"]["sorted_diagnostics_sha256"]:
        raise RegenVerificationError("Fresh re-execution canonical-validation digest does not match recorded run_1")
    if fresh_cv.get("total_diagnostics") != 244:
        raise RegenVerificationError(f"Fresh re-execution total_diagnostics expected 244, got {fresh_cv.get('total_diagnostics')}")
    fresh_bootstrap_manifest = fresh.get("bootstrap_execution", {}).get("manifest")
    if fresh_bootstrap_manifest != data["run_1"]["bootstrap_execution"]["manifest"]:
        raise RegenVerificationError("Fresh re-execution bootstrap manifest does not match recorded run_1")
    if fresh.get("baseline_tree_oid") != tree_oid:
        raise RegenVerificationError(f"Fresh re-execution baseline_tree_oid {fresh.get('baseline_tree_oid')!r} does not match pinned {tree_oid!r}")
    if fresh.get("tool_pins") != data["run_1"]["tool_pins"]:
        raise RegenVerificationError("Fresh re-execution tool_pins do not match recorded run_1 (possible tool substitution)")
    fresh_cov = fresh.get("oversized_coverage") or {}
    for path in expected_oversized:
        if fresh_cov.get(path, {}).get("sha256") != cov[path]["sha256"]:
            raise RegenVerificationError(f"Fresh re-execution oversized sha256 for {path} does not match recorded run_1")

    return True


def run_negative_harness(reference_json_path, repo_dir):
    with open(reference_json_path) as f:
        base_data = json.load(f)

    cases = []

    def _case(case_id, name, mutate_fn):
        import copy
        mutated_path = None
        try:
            mutated = copy.deepcopy(base_data)
            mutate_fn(mutated)
            tmp = tempfile.NamedTemporaryFile(mode="w", suffix=".json", delete=False)
            json.dump(mutated, tmp)
            tmp.close()
            mutated_path = tmp.name
